async function toggleControl(cb){const type=cb.dataset.type,id=cb.dataset.id,index=Number(cb.dataset.index),row=arr(type).find(x=>x.id===id);if(!row)return;const values=checkArray(type,row);values[index]=cb.checked;cb.disabled=true;try{await global.CizelgelerService.kontrolToggle(type,id,values);row.kontroller=values;render(true)}catch(e){cb.checked=!cb.checked;global.toast?.(e?.message==='yetkisiz'?'Bu işlem için yetkiniz yok.':'İşaretleme kaydedilemedi.')}finally{cb.disabled=false}}
function teachersChecks(name,selected=[]){const set=new Set(Array.isArray(selected)?selected:[]);return `<div class="ka-stack" style="max-height:210px;overflow:auto;border:1px solid var(--ka-border);border-radius:12px;padding:8px">${arr('ogretmenler').slice().sort((a,b)=>`${a.ad||''} ${a.soyad||''}`.localeCompare(`${b.ad||''} ${b.soyad||''}`,'tr')).map(o=>`<label class="ka-row"><input type="checkbox" name="${name}" value="${esc(o.id)}" ${set.has(o.id)?'checked':''}><span>${esc(`${o.ad||''} ${o.soyad||''}`.trim())}</span></label>`).join('')||'<span class="ka-muted">Öğretmen bulunamadı.</span>'}</div>`}
function teacherSelect(name,value=''){return `<select name="${name}" required><option value="">— Seçiniz —</option>${arr('ogretmenler').slice().sort((a,b)=>`${a.ad||''} ${a.soyad||''}`.localeCompare(`${b.ad||''} ${b.soyad||''}`,'tr')).map(o=>`<option value="${esc(o.id)}" ${o.id===value?'selected':''}>${esc(`${o.ad||''} ${o.soyad||''}`.trim())}</option>`).join('')}</select>`}
function classSelect(name,value='',optional=false){return `<select name="${name}" ${optional?'':'required'}><option value="">${optional?'— Seçiniz (opsiyonel) —':'— Seçiniz —'}</option>${arr('siniflar').slice().sort((a,b)=>String(a.ad||'').localeCompare(String(b.ad||''),'tr',{numeric:true})).map(s=>`<option value="${esc(s.ad||'')}" ${String(s.ad||'')===String(value||'')?'selected':''}>${esc(s.ad||'')}</option>`).join('')}</select>`}
function classChecks(name,selected=[],useId=false,quick=false){const set=new Set(Array.isArray(selected)?selected:[]),quickBar=quick?`<div class="ka-row ka-wrap" style="gap:6px"><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-class-level-quick="primary">🧒 Tüm İlkokul (1-4)</button><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-class-level-quick="middle">🎓 Tüm Ortaokul (5-8)</button><button class="ka-btn ka-btn--secondary ka-btn--sm" type="button" data-class-level-quick="clear">✕ Temizle</button></div>`:'';return `${quickBar}<div class="ka-stack" style="max-height:190px;overflow:auto;border:1px solid var(--ka-border);border-radius:12px;padding:8px">${arr('siniflar').slice().sort((a,b)=>String(a.ad||'').localeCompare(String(b.ad||''),'tr',{numeric:true})).map(s=>{const v=useId?s.id:s.ad;return`<label class="ka-row"><input type="checkbox" name="${name}" value="${esc(v||'')}" data-seviye="${esc(s.seviye||'')}" ${set.has(v)?'checked':''}><span>${esc(s.ad||'')}</span></label>`}).join('')||'<span class="ka-muted">Sınıf bulunamadı.</span>'}</div>${quick?'<small class="ka-muted">Hiç sınıf seçilmezse bu kulübü tüm sınıflar seçebilir.</small>':''}`;}
